using LankaSaaS.Application;using LankaSaaS.Domain;using LankaSaaS.Infrastructure;using Microsoft.EntityFrameworkCore;
public static class PurchasingEndpoints
{
 public static void Map(WebApplication app){var s=app.MapGroup("/api/suppliers").RequireAuthorization();s.MapGet("/",async(AppDbContext db)=>Results.Ok(await db.Suppliers.OrderBy(x=>x.Name).Select(x=>new SupplierDto(x.Id,x.Name,x.ContactName,x.Phone,x.Email,x.Address)).ToListAsync()));s.MapPost("/",CreateSupplier).AddEndpointFilter<ValidationFilter>();var p=app.MapGroup("/api/purchase-orders").RequireAuthorization();p.MapGet("/",List);p.MapPost("/",Create).AddEndpointFilter<ValidationFilter>();p.MapPatch("/{id:guid}/status/{status}",ChangeStatus);p.MapPost("/{id:guid}/payments",Pay).AddEndpointFilter<ValidationFilter>();}
 static async Task<IResult> CreateSupplier(SupplierRequest r,AppDbContext db){var x=new Supplier{Name=r.Name.Trim(),ContactName=Clean(r.ContactName),Phone=Clean(r.Phone),Email=Clean(r.Email)?.ToLowerInvariant(),Address=Clean(r.Address)};db.Suppliers.Add(x);await db.SaveChangesAsync();return Results.Created($"/api/suppliers/{x.Id}",new SupplierDto(x.Id,x.Name,x.ContactName,x.Phone,x.Email,x.Address));}
 static async Task<IResult> List(AppDbContext db){var orders=await db.PurchaseOrders.Include(x=>x.Items).OrderByDescending(x=>x.OrderDate).ToListAsync();var paid=await db.SupplierPayments.GroupBy(x=>x.PurchaseOrderId).Select(x=>new{x.Key,Amount=x.Sum(y=>y.Amount)}).ToDictionaryAsync(x=>x.Key,x=>x.Amount);return Results.Ok(orders.Select(x=>Dto(x,paid.GetValueOrDefault(x.Id))).ToList());}
 static async Task<IResult> Create(PurchaseOrderRequest r,AppDbContext db,ITenantContext tenant){if(r.Type is not (PurchaseOrderTypes.Purchase or PurchaseOrderTypes.Rental))return Results.BadRequest(new{message="Type must be Purchase or Rental."});if(r.Type==PurchaseOrderTypes.Rental&&(r.RentalStartDate is null||r.RentalEndDate<r.RentalStartDate))return Results.BadRequest(new{message="Enter valid rental dates."});var supplier=await db.Suppliers.SingleOrDefaultAsync(x=>x.Id==r.SupplierId);if(supplier is null)return Results.BadRequest(new{message="Supplier was not found."});if(r.EventId.HasValue&&!await db.Events.AnyAsync(x=>x.Id==r.EventId))return Results.BadRequest(new{message="Event was not found."});var resourceIds=r.Items.Where(x=>x.ResourceId.HasValue).Select(x=>x.ResourceId!.Value).Distinct().ToList();if(resourceIds.Count>0&&await db.LogisticsResources.CountAsync(x=>resourceIds.Contains(x.Id))!=resourceIds.Count)return Results.BadRequest(new{message="A resource was not found."});var x=new PurchaseOrder{SupplierId=supplier.Id,SupplierName=supplier.Name,EventId=r.EventId,Type=r.Type,OrderDate=r.OrderDate,RentalStartDate=r.RentalStartDate,RentalEndDate=r.RentalEndDate,Notes=Clean(r.Notes)};x.Items=r.Items.Select(i=>new PurchaseOrderItem{TenantId=tenant.TenantId,ResourceId=i.ResourceId,Description=i.Description.Trim(),Quantity=i.Quantity,UnitCost=i.UnitCost,LineTotal=Math.Round(i.Quantity*i.UnitCost,2)}).ToList();x.Total=x.Items.Sum(i=>i.LineTotal);db.PurchaseOrders.Add(x);await db.SaveChangesAsync();return Results.Created($"/api/purchase-orders/{x.Id}",Dto(x,0));}
 static async Task<IResult> ChangeStatus(Guid id,string status,AppDbContext db,ITenantContext tenant){var x=await db.PurchaseOrders.Include(x=>x.Items).SingleOrDefaultAsync(x=>x.Id==id);if(x is null)return Results.NotFound();var valid=x.Status switch{PurchaseOrderStatuses.Draft=>status is PurchaseOrderStatuses.Ordered or PurchaseOrderStatuses.Cancelled,PurchaseOrderStatuses.Ordered=>status is PurchaseOrderStatuses.Received or PurchaseOrderStatuses.Cancelled,_=>false};if(!valid)return Results.Conflict(new{message=$"Cannot change order from {x.Status} to {status}."});if(status==PurchaseOrderStatuses.Received){await using var tx=await db.Database.BeginTransactionAsync();await db.Database.ExecuteSqlInterpolatedAsync($"SELECT pg_advisory_xact_lock(hashtext({x.Id.ToString()}))");if(await db.Expenses.AnyAsync(e=>e.PurchaseOrderId==x.Id))return Results.Conflict(new{message="This order was already received."});if(x.Type==PurchaseOrderTypes.Purchase){foreach(var item in x.Items.Where(i=>i.ResourceId.HasValue)){var resource=await db.LogisticsResources.SingleAsync(r=>r.Id==item.ResourceId);if(item.Quantity!=decimal.Truncate(item.Quantity))return Results.BadRequest(new{message="Owned resource quantities must be whole numbers."});resource.TotalQuantity+=decimal.ToInt32(item.Quantity);}}db.Expenses.Add(new Expense{TenantId=tenant.TenantId,EventId=x.EventId,PurchaseOrderId=x.Id,Description=$"{x.Type} order from {x.SupplierName}",Category=x.Type==PurchaseOrderTypes.Rental?"Equipment rental":"Purchasing",Amount=x.Total,ExpenseDate=DateOnly.FromDateTime(DateTime.UtcNow)});x.Status=status;await db.SaveChangesAsync();await tx.CommitAsync();return Results.NoContent();}x.Status=status;await db.SaveChangesAsync();return Results.NoContent();}
 static async Task<IResult> Pay(Guid id,SupplierPaymentRequest r,AppDbContext db){var x=await db.PurchaseOrders.SingleOrDefaultAsync(x=>x.Id==id);if(x is null)return Results.NotFound();if(x.Status==PurchaseOrderStatuses.Cancelled)return Results.Conflict(new{message="Cancelled orders cannot be paid."});var paid=await db.SupplierPayments.Where(p=>p.PurchaseOrderId==id).SumAsync(p=>(decimal?)p.Amount)??0;if(paid+r.Amount>x.Total)return Results.Conflict(new{message=$"Payment exceeds the outstanding balance of {x.Total-paid:0.00}."});db.SupplierPayments.Add(new SupplierPayment{PurchaseOrderId=id,Amount=r.Amount,PaymentDate=r.PaymentDate,Method=r.Method.Trim(),Reference=Clean(r.Reference)});await db.SaveChangesAsync();return Results.NoContent();}
 static PurchaseOrderDto Dto(PurchaseOrder x,decimal paid)=>new(x.Id,x.SupplierId,x.SupplierName,x.EventId,x.Type,x.Status,x.OrderDate,x.RentalStartDate,x.RentalEndDate,x.Total,paid,x.Total-paid,x.Notes,x.Items.Select(i=>new PurchaseOrderItemRequest(i.ResourceId,i.Description,i.Quantity,i.UnitCost)).ToList());static string? Clean(string? x)=>string.IsNullOrWhiteSpace(x)?null:x.Trim();
}
